    grid = observation.get('grid', [])
    agent_pos = observation.get('agent_pos', (0, 0))
    width = len(grid[0]) if grid else 0
    height = len(grid)

    # Extract agent coordinates
    x, y = agent_pos

    # Define possible moves
    moves = {
        'UP': (0, -1),
        'DOWN': (0, 1),
        'LEFT': (-1, 0),
        'RIGHT': (1, 0),
        'STAY': (0, 0)
    }

    # Helper to check if position is within bounds and free
    def is_free(nx, ny):
        if 0 <= ny < height and 0 <= nx < width:
            cell = grid[ny][nx]
            # Assuming passable if not obstacle (assuming obstacles are marked)
            return cell != 'O'  # O for obstacle, adjust if different
        return False

    # Gather resource positions if resource_collection
    resources = []
    if 'resource' in observation.get('task', ''):
